using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class InspectDesk {
 public static object Run(){var s=SceneManager.GetActiveScene();var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var t=ts.Single(t=>t.name=="B4_E02_TaskLightPole_13");var rows=ts.Where(q=>(q.position-t.position).magnitude<5&&q.GetComponent<Collider>()).Select(q=>new{name=q.name,p=q.position.ToString("F3"),scale=q.lossyScale.ToString(),colliders=q.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,enabled=c.enabled,center=c.bounds.center.ToString("F3"),size=c.bounds.size.ToString("F3"),localCenter=c is BoxCollider b?b.center.ToString():null,localSize=c is BoxCollider bb?bb.size.ToString():null}),renderers=q.GetComponentsInChildren<Renderer>().Select(r=>new{name=r.name,center=r.bounds.center.ToString("F3"),size=r.bounds.size.ToString("F3")})}).ToArray();var desk=ts.Where(q=>q.name.Contains("ProtocolTable")&&PrefabUtility.IsAnyPrefabInstanceRoot(q.gameObject)).Select(q=>new{name=q.name,p=q.position.ToString("F3"),e=q.eulerAngles.ToString(),children=q.GetComponentsInChildren<Transform>().Select(x=>new{name=x.name,p=x.localPosition.ToString(),mesh= x.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(x.GetComponent<MeshFilter>().sharedMesh):null})});var result=new{playing=Application.isPlaying,dirty=s.isDirty,player=UnityEngine.Object.FindAnyObjectByType<CharacterController>()?.transform.position.ToString(),selected=Selection.activeGameObject?Selection.activeGameObject.name:null,rows,desk};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/FloorSurfaceWear/desk_obstacles_before.json")),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
